import { notFound } from "next/navigation";

import { getContent, isLocale } from "@/content";
import { Container } from "@/shared/components/Container";
import { SectionHeading } from "@/shared/components/SectionHeading";

type LocalePageProps = Readonly<{
  params: Promise<{ locale: string }>;
}>;

export default async function LocalePage({ params }: LocalePageProps) {
  const { locale } = await params;

  if (!isLocale(locale)) {
    notFound();
  }

  const content = getContent(locale);

  return (
    <main className="technical-grid" id="top">
      <Container className="py-20 sm:py-28">
        <SectionHeading
          description={content.foundation.description}
          eyebrow={content.foundation.eyebrow}
          id="foundation-title"
          title={content.foundation.title}
        />
        <p className="mt-6 text-sm font-semibold text-[var(--color-accent)]">
          {content.foundation.statusLabel}
        </p>
      </Container>
    </main>
  );
}
